--- a/cron.fixes.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/cron.fixes.test.ts	2026-10-28 07:46:19.057302349 +0000
@@ -0,0 +1,68 @@
+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("a step from a single value runs to the end of the field", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:05:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:25:00Z")).toISOString()).toBe("2026-01-01T00:45:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:45:00Z")).toISOString()).toBe("2026-01-01T01:05:00.000Z");
+});
+
+test("a step over a range", () => {
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:15:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:10:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:10:00Z")).toISOString()).toBe("2026-01-01T00:20:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:30:00Z")).toISOString()).toBe("2026-01-01T01:10:00.000Z");
+});
+
+test("month and weekday names, in any case", () => {
+  expect(nextRun("0 0 1 mar *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-03-01T00:00:00.000Z");
+  expect(nextRun("0 0 * * SUN", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(nextRun("0 0 * Jan-Mar Mon-Fri", at("2026-01-01T00:00:00Z")).toISOString()).toBe(
+    "2026-01-02T00:00:00.000Z",
+  );
+});
+
+test("Sunday as 7", () => {
+  expect(nextRun("0 0 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(nextRun("0 0 * * 7", at("2026-01-04T00:00:00Z")).toISOString()).toBe("2026-01-11T00:00:00.000Z");
+  expect(nextRun("0 0 * * 0", at("2026-01-04T00:00:00Z")).toISOString()).toBe("2026-01-11T00:00:00.000Z");
+});
+
+test("both a day of month and a day of week", () => {
+  const expr = "0 0 1,15 * 1";
+  expect(nextRun(expr, at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun(expr, at("2026-01-05T00:00:00Z")).toISOString()).toBe("2026-01-12T00:00:00.000Z");
+  expect(nextRun(expr, at("2026-01-12T00:00:00Z")).toISOString()).toBe("2026-01-15T00:00:00.000Z");
+  expect(nextRun(expr, at("2026-01-15T00:00:00Z")).toISOString()).toBe("2026-01-19T00:00:00.000Z");
+});
+
+test("a day field that covers its whole range is not restricted", () => {
+  expect(nextRun("0 0 1-31 * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 15 * 0-6", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-15T00:00:00.000Z");
+});
+
+test("the 29th of February", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+  expect(nextRun("0 0 29 2 *", at("2096-03-01T00:00:00Z")).toISOString()).toBe("2104-02-29T00:00:00.000Z");
+});
+
+test("an expression that never fires", () => {
+  expect(() => nextRun("0 0 30 2 *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("invalid expressions", () => {
+  for (const expr of [
+    "*/0 * * * *",
+    "10-5 * * * *",
+    "* * * FOO *",
+    "* * * * 8",
+    "*/1x * * * *",
+    "5/2/1 * * * *",
+    "1,,2 * * * *",
+  ]) {
+    expect(() => nextRun(expr, at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+  }
+});
