+    expect(satisfies(bad, "*")).toBe(false);
+  }
+  expect(satisfies("  v1.2.3+build.5 ", "1.2.3")).toBe(true);
+  expect(satisfies("1.2.3 ", "1.2.3")).toBe(true);
+  expect(satisfies("1.2.3-0", "1.2.3-0")).toBe(true);
+  expect(satisfies("1.2.3-0a", "1.2.3-0a")).toBe(true);
+});
